// FastAPI 文件上传路由 - 处理用户头像上传
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const router = express.Router();

// 配置 multer 存储
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const uploadDir = path.join(__dirname, '../uploads/avatars');
    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir, { recursive: true });
    }
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    // 生成随机文件名，避免路径遍历
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    cb(null, uniqueSuffix + path.extname(file.originalname));
  }
});

// 文件过滤器 - 白名单扩展名
const fileFilter = (req, file, cb) => {
  const allowedExt = ['.jpg', '.jpeg', '.png', '.gif'];
  const ext = path.extname(file.originalname).toLowerCase();

  // 防御1: 扩展名白名单
  if (!allowedExt.includes(ext)) {
    return cb(new Error('仅允许上传图片文件'), false);
  }

  // 防御2: 检查 MIME 类型
  const allowedMime = ['image/jpeg', 'image/png', 'image/gif'];
  if (!allowedMime.includes(file.mimetype)) {
    return cb(new Error('文件类型不合法'), false);
  }

  cb(null, true);
};

const upload = multer({ 
  storage: storage,
  fileFilter: fileFilter,
  limits: { fileSize: 5 * 1024 * 1024 } // 5MB 限制
});

// 上传端点
router.post('/upload', upload.single('avatar'), (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: '未收到文件' });
  }

  // 防御3: 重新验证文件扩展名（防止 MIME 欺骗）
  const originalExt = path.extname(req.file.originalname).toLowerCase();
  const allowedExt = ['.jpg', '.jpeg', '.png', '.gif'];

  if (!allowedExt.includes(originalExt)) {
    // 删除已上传的非法文件
    fs.unlink(req.file.path, (err) => {
      if (err) console.error('清理失败:', err);
    });
    return res.status(400).json({ error: '文件扩展名不合法' });
  }

  // 防御4: 验证文件名不包含路径分隔符（防止路径遍历）
  const baseName = path.basename(req.file.filename);
  if (baseName !== req.file.filename) {
    fs.unlink(req.file.path, (err) => {
      if (err) console.error('清理失败:', err);
    });
    return res.status(400).json({ error: '文件名不合法' });
  }

  // 安全地构建文件访问 URL
  const safeFilename = req.file.filename.replace(/[^a-zA-Z0-9._-]/g, '');
  const fileUrl = `/uploads/avatars/${safeFilename}`;

  res.json({
    success: true,
    fileUrl: fileUrl,
    size: req.file.size
  });
});

// 错误处理中间件
router.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    return res.status(400).json({ error: '上传错误: ' + err.message });
  }
  if (err) {
    return res.status(400).json({ error: err.message });
  }
  next();
});

module.exports = router;

