import io.javalin.Javalin;
import io.javalin.http.Context;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.regex.Pattern;

public class AuthController {
    private static final Pattern USERNAME_PATTERN = Pattern.compile("^[a-zA-Z0-9_]{3,20}$");
    private final Connection db;

    public AuthController(Connection db) {
        this.db = db;
    }

    public void registerRoutes(Javalin app) {
        app.post("/api/login", this::login);
    }

    private void login(Context ctx) {
        String username = ctx.formParam("username");
        String password = ctx.formParam("password");

        // 迷惑防御：看似用 replace 转义，实际不用于 SQL 构造
        String escapedUsername = username.replace("'", "''");
        if (escapedUsername == null || escapedUsername.isEmpty()) {
            ctx.status(400).result("用户名不能为空");
            return;
        }

        // 真正的防御：白名单正则校验
        if (!USERNAME_PATTERN.matcher(escapedUsername).matches()) {
            ctx.status(400).result("用户名格式非法");
            return;
        }

        // 真正的防御：参数化查询
        try (PreparedStatement ps = db.prepareStatement(
                "SELECT id, password_hash FROM users WHERE username = ? AND active = 1")) {
            ps.setString(1, escapedUsername);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    String storedHash = rs.getString("password_hash");
                    if (PasswordUtil.verify(password, storedHash)) {
                        ctx.sessionAttribute("userId", rs.getInt("id"));
                        ctx.status(200).result("登录成功");
                    } else {
                        ctx.status(401).result("密码错误");
                    }
                } else {
                    ctx.status(404).result("用户不存在");
                }
            }
        } catch (SQLException e) {
            ctx.status(500).result("服务器内部错误");
        }
    }
}

