// sortWhitelist 枚举外部允许的排序键并映射为固定 SQL 列名，键值均为开发者写死的字面量
var sortWhitelist = map[string]string{
	"name":   "image_name",
	"format": "image_format",
	"size":   "byte_size",
	"ctime":  "created_at",
}

// QueryImageMeta 按外部排序键检索图片处理流水线的元数据
func QueryImageMeta(db *sql.DB, sortBy string) ([]ImageMeta, error) {
	col, ok := sortWhitelist[sortBy] // 精确匹配白名单，未命中即拒绝
	if !ok {
		return nil, fmt.Errorf("unsupported sort key")
	}
	// 进入 SQL 的标识符只能取自 map 值字面量，sortBy 本身永不拼接
	query := fmt.Sprintf("SELECT id, image_name, image_format, byte_size FROM image_meta ORDER BY %s ASC", col)
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []ImageMeta
	for rows.Next() {
		var m ImageMeta
		if err := rows.Scan(&m.ID, &m.Name, &m.Format, &m.Size); err != nil {
			return nil, err
		}
		out = append(out, m)
	}
	return out, rows.Err()
}
