// SyncTask 为数据同步工作线程的任务单元
type SyncTask struct {
	RecordID string `json:"record_id"`
}

// WorkerPool 持有任务队列, 由后台工作 goroutine 消费
type WorkerPool struct{ tasks chan SyncTask }

// 入口1: 主同步接口, 记录ID先经 sanitizeLogField 净化再入队
func (p *WorkerPool) handleSync(w http.ResponseWriter, r *http.Request) {
	clean := sanitizeLogField(r.URL.Query().Get("record_id"))
	p.tasks <- SyncTask{RecordID: clean}
	json.NewEncoder(w).Encode(map[string]string{"status": "queued"})
}

// 入口2: 失败重试接口, 请求体中的原始ID未净化直接入队
func (p *WorkerPool) handleRetry(w http.ResponseWriter, r *http.Request) {
	var req SyncTask
	if json.NewDecoder(r.Body).Decode(&req) != nil {
		http.Error(w, "bad request", 400)
		return
	}
	p.tasks <- req
	json.NewEncoder(w).Encode(map[string]string{"status": "retry-queued"})
}

func main() {
	p := &WorkerPool{tasks: make(chan SyncTask, 64)}
	go p.worker()
	http.HandleFunc("/sync", p.handleSync)
	http.HandleFunc("/retry", p.handleRetry)
	http.HandleFunc("/purge", p.handlePurge)
	http.ListenAndServe(":8080", nil)
}
